import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Concetto di asintoto","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/ch/cha.md","filePath":"lezioni/c_analisi/ch/cha.md"}`),a={name:`lezioni/c_analisi/ch/cha.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="concetto-di-asintoto" tabindex="-1">Concetto di asintoto <a class="header-anchor" href="#concetto-di-asintoto" aria-label="Permalink to “Concetto di asintoto”">​</a></h1><p>[Asintoto]{.text-red} è una parola che deriva dal greco: a privativo che significa no e sympìptein che significa congiungere, cioè significa [che non tocca]{.text-red}, in pratica si tratta di una retta che si avvicina alla funzione senza mai toccarla, per questo si dice anche che l&#39;asintoto è [la tangente all&#39;infinito della funzione]{.text-red}.</p><p>Quindi se non sappiamo come si comporta una funzione all&#39;infinito sappiamo però come all&#39;infinito si comporta una retta e se troviamo l&#39;equazione della retta che accompagna la funzione all&#39;infinito (asintoto) potremo tracciare il grafico della funzione che tende all&#39;infinito con buona approssimazione.</p><p>Una funzione può tendere all&#39;infinito avvicinandosi ad una retta in tre modi diversi:</p><ul><li>Asintoto verticale: quando la <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> si avvicina ad un valore finito la funzione tende all&#39;infinito avvicinandosi ad una retta verticale.</li><li>Asintoto orizzontale: quando la <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> tende all&#39;infinito la funzione si avvicina ad una retta orizzontale.</li><li>Asintoto obliquo: quando la <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> tende all&#39;infinito la funzione tende all&#39;infinito avvicinandosi ad una retta obliqua.</li></ul><blockquote><p><strong>Nota:</strong> Da notare che l&#39;asintoto orizzontale esclude l&#39;asintoto obliquo e viceversa perché al crescere della <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> la funzione può andare all&#39;infinito in un solo modo.</p></blockquote>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};